queries.sparql:
SELECT ?class ?anchor WHERE {
  ?class a owl:Class ; rdfs:subClassOf ?anchor .
  FILTER(STRSTARTS(STR(?class), "https://w3id.org/brec/ontology#"))
  FILTER(STRSTARTS(STR(?anchor), "http://www.cidoc-crm.org/") || STRSTARTS(STR(?anchor), "http://www.cidoc-crm.org/extensions/") || STRSTARTS(STR(?anchor), "http://www.ics.forth.gr/isl/CRMinf/"))
}
ORDER BY ?anchor ?class

SELECT ?object ?hypothesis ?confidence ?status WHERE {
  ?h brec:hypothesisAbout ?o ; brec:confidence ?confidence ; rdfs:label ?hypothesis .
  FILTER(LANG(?hypothesis) = "en")
  ?o rdfs:label ?object .
  FILTER(LANG(?object) = "en" || LANG(?object) = "")
  OPTIONAL { ?h brec:verificationStatus ?status . FILTER(LANG(?status) = "en") }
}
ORDER BY ?object DESC(?confidence)

SELECT ?identification ?evidence WHERE {
  ?i crminf:J1_used_as_premise ?e .
  ?i rdfs:label ?identification . FILTER(LANG(?identification) = "en")
  ?e rdfs:label ?evidence . FILTER(LANG(?evidence) = "en")
}
ORDER BY ?identification ?evidence

SELECT ?model ?device ?photos (MIN(?placeLabel) AS ?place) ?wikidata WHERE {
  ?event a brec:ScanDigitization ; crmdig:L1_digitized ?m ; brec:captureDevice ?device ; brec:imageCount ?photos ; crm:P7_took_place_at ?p .
  ?m rdfs:label ?model . FILTER(LANG(?model) = "en")
  ?p rdfs:label ?placeLabel . FILTER(LANG(?placeLabel) = "en")
  OPTIONAL { ?p skos:closeMatch ?wikidata }
}
GROUP BY ?model ?device ?photos ?wikidata
ORDER BY ?model

SELECT ?concept ?title ?version WHERE {
  ?concept a brec:FDOx ; dct:title ?title .
  OPTIONAL { ?concept dct:hasVersion ?version }
}
ORDER BY ?title

SELECT ?property ?domain ?range WHERE {
  { ?property a owl:ObjectProperty } UNION { ?property a owl:DatatypeProperty }
  FILTER(STRSTARTS(STR(?property), "https://w3id.org/brec/ontology#"))
  OPTIONAL { ?property rdfs:domain ?domain }
  OPTIONAL { ?property rdfs:range ?range }
}
ORDER BY ?property
